def icon(
    name: str,
    size: int = 20,
    color: str = "currentColor",
    stroke_width: float = 2,
    filled: bool = False,
) -> str:
    """指定したアイコンのSVGタグを文字列で返す。

    filled=True にすると、塗りつぶしたアイコンにする
    （お気に入り済みのハートなど、状態の違いを表すときに使う）。
    """
    inner = _PATHS[name.replace("-", "_")]
    fill = color if filled else "none"
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="{fill}" stroke="{color}" stroke-width="{stroke_width}" '
        f'stroke-linecap="round" stroke-linejoin="round" '
        f'style="vertical-align:-0.2em">{inner}</svg>'
    )
